// Local ZeroTier control bridge. Credentials are generated by ZeroTier on this
// device, transferred once through an ACL-protected named pipe after UAC, and
// protected using Windows DPAPI CurrentUser. No credential is bundled or logged.
using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Pipes;
using System.Text;
using System.Net;
using System.Diagnostics;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Security.Cryptography;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Web.Script.Serialization;
using Microsoft.Win32.SafeHandles;

internal static class OverlayBridge {
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
    struct ProcessEntry {
        public uint dwSize, cntUsage, th32ProcessID;
        public UIntPtr th32DefaultHeapID;
        public uint th32ModuleID, cntThreads, th32ParentProcessID;
        public int pcPriClassBase;
        public uint dwFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=260)] public string szExeFile;
    }
    [DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr CreateToolhelp32Snapshot(uint flags,uint processId);
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode)] static extern bool Process32First(IntPtr snapshot,ref ProcessEntry entry);
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode)] static extern bool Process32Next(IntPtr snapshot,ref ProcessEntry entry);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr handle);
    static object ProcessMetrics(string text) {
        int root; if(!Int32.TryParse(text,out root)||root<1)throw new Exception("Invalid process");
        var parents=new Dictionary<int,int>();
        IntPtr snapshot=CreateToolhelp32Snapshot(2,0);
        if(snapshot==new IntPtr(-1))throw new Exception("Snapshot unavailable");
        try {
            var entry=new ProcessEntry();entry.dwSize=(uint)Marshal.SizeOf(typeof(ProcessEntry));
            if(Process32First(snapshot,ref entry))do{parents[(int)entry.th32ProcessID]=(int)entry.th32ParentProcessID;}while(parents.Count<16384&&Process32Next(snapshot,ref entry));
        } finally {CloseHandle(snapshot);}
        var owned=new HashSet<int>();owned.Add(root);
        for(int depth=0;depth<8;depth++){bool added=false;foreach(var p in parents)if(owned.Count<128&&owned.Contains(p.Value)&&owned.Add(p.Key))added=true;if(!added)break;}
        var result=new List<object>();
        foreach(int pid in owned)try{using(var p=Process.GetProcessById(pid)){result.Add(new{pid=pid,startedAtMs=(p.StartTime.ToUniversalTime()-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalMilliseconds,cpuSeconds=p.TotalProcessorTime.TotalSeconds,workingSetBytes=p.WorkingSet64});}}catch{}
        return result;
    }
    static readonly JavaScriptSerializer Json = new JavaScriptSerializer();
    static readonly byte[] Entropy = Encoding.UTF8.GetBytes("FriendScreen-overlay-auth-v1");
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool GetNamedPipeServerProcessId(SafePipeHandle pipe, out uint processId);
    static string Self { get { return Assembly.GetExecutingAssembly().Location; } }
    static string Quote(string text) { return "\"" + text.Replace("\"", "") + "\""; }
    static string TokenFile(string folder) { return Path.Combine(folder, "zerotier-auth.dpapi"); }
    static bool ValidNetwork(string id) { return System.Text.RegularExpressions.Regex.IsMatch(id ?? "", "\\A[0-9a-fA-F]{16}\\z"); }
    static void Elevated(string pipeName) {
        if (!System.Text.RegularExpressions.Regex.IsMatch(pipeName, "\\AFriendScreen-[a-f0-9]{32}\\z")) throw new Exception("本机授权请求无效");
        using (var pipe = new NamedPipeClientStream(".", pipeName, PipeDirection.Out, PipeOptions.None)) {
            pipe.Connect(10000);
            uint pid;
            if (!GetNamedPipeServerProcessId(pipe.SafePipeHandle, out pid)) throw new Exception("无法核对本机授权进程");
            var process = Process.GetProcessById((int)pid);
            if (!String.Equals(Path.GetFullPath(process.MainModule.FileName), Path.GetFullPath(Self), StringComparison.OrdinalIgnoreCase)) throw new Exception("本机授权程序不匹配");
            string source = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "ZeroTier", "One", "authtoken.secret");
            string token = File.ReadAllText(source).Trim();
            if (token.Length < 16 || token.Length > 256 || token.IndexOfAny(new char[]{'\r','\n'}) >= 0) throw new Exception("网络组件凭证无效");
            using (var writer = new StreamWriter(pipe, new UTF8Encoding(false))) { writer.WriteLine(token); }
        }
    }
    static void Bootstrap(string folder) {
        var principal = WindowsIdentity.GetCurrent().User;
        var acl = new PipeSecurity();
        acl.SetAccessRuleProtection(true, false);
        acl.AddAccessRule(new PipeAccessRule(principal, PipeAccessRights.FullControl, AccessControlType.Allow));
        acl.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid, null), PipeAccessRights.ReadWrite, AccessControlType.Allow));
        string name = "FriendScreen-" + Guid.NewGuid().ToString("N");
        using (var pipe = new NamedPipeServerStream(name, PipeDirection.In, 1, PipeTransmissionMode.Byte, PipeOptions.Asynchronous, 4096, 4096, acl)) {
            var wait = pipe.BeginWaitForConnection(null, null);
            var info = new ProcessStartInfo(Self, "--elevated " + name) { UseShellExecute = true, Verb = "runas", WindowStyle = ProcessWindowStyle.Hidden, WorkingDirectory = Path.GetDirectoryName(Self) };
            using (var child = Process.Start(info)) {
                if (!wait.AsyncWaitHandle.WaitOne(120000)) throw new Exception("Windows 授权超时，请重试并确认 UAC");
                pipe.EndWaitForConnection(wait);
                using (var reader = new StreamReader(pipe, Encoding.UTF8)) {
                    string token = reader.ReadLine();
                    if (String.IsNullOrEmpty(token) || token.Length > 256) throw new Exception("未收到网络组件授权");
                    byte[] encrypted = ProtectedData.Protect(Encoding.UTF8.GetBytes(token), Entropy, DataProtectionScope.CurrentUser);
                    Directory.CreateDirectory(folder);
                    string file = TokenFile(folder), temp = file + ".tmp";
                    File.WriteAllBytes(temp, encrypted);
                    if (File.Exists(file)) File.Delete(file);
                    File.Move(temp, file);
                }
            }
        }
    }
    static string Request(string folder, string method, string endpoint, string body) {
        if (!File.Exists(TokenFile(folder))) throw new Exception("此 Windows 用户尚未授权网络组件，请点击首次设置中的 Windows 授权");
        string token = Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(TokenFile(folder)), Entropy, DataProtectionScope.CurrentUser));
        var req = (HttpWebRequest)WebRequest.Create("http://127.0.0.1:9993" + endpoint);
        req.Proxy = null; req.AllowAutoRedirect = false; req.Method = method; req.Timeout = 5000; req.ReadWriteTimeout = 5000;
        req.Headers.Add("X-ZT1-Auth", token);
        if (body != null) { byte[] bytes = Encoding.UTF8.GetBytes(body); req.ContentType = "application/json"; req.ContentLength = bytes.Length; using(var stream=req.GetRequestStream()) stream.Write(bytes,0,bytes.Length); }
        using(var response=(HttpWebResponse)req.GetResponse()) using(var reader=new StreamReader(response.GetResponseStream())) return reader.ReadToEnd();
    }
    static int Main(string[] args) {
        Console.OutputEncoding = new UTF8Encoding(false);
        try {
            if(args.Length==2&&args[0]=="metrics"){Console.WriteLine(Json.Serialize(new{ok=true,result=ProcessMetrics(args[1])}));return 0;}
            if (args.Length == 2 && args[0] == "--elevated") { Elevated(args[1]); return 0; }
            if (args.Length < 2) throw new Exception("缺少本机网络操作参数");
            string operation=args[0], folder=Path.GetFullPath(args[1]);
            if(operation=="authorize") { Bootstrap(folder); Console.WriteLine("{\"ok\":true}"); return 0; }
            string result;
            if(operation=="status" && args.Length==2) result=Request(folder,"GET","/status",null);
            else if(operation=="peers" && args.Length==2) result=Request(folder,"GET","/peer",null);
            else if(args.Length==3 && ValidNetwork(args[2])) {
                string network=args[2].ToLowerInvariant();
                if(operation=="network") result=Request(folder,"GET","/network/"+network,null);
                else if(operation=="join") result=Request(folder,"POST","/network/"+network,"{\"allowManaged\":true,\"allowGlobal\":false,\"allowDefault\":false,\"allowDNS\":false}");
                else if(operation=="leave") result=Request(folder,"DELETE","/network/"+network,null);
                else throw new Exception("不支持的本机网络操作");
            } else throw new Exception("Network ID 格式错误");
            // Only the selected operation's public result is returned, never the token.
            Console.WriteLine("{\"ok\":true,\"result\":"+result+"}");
            return 0;
        } catch(System.ComponentModel.Win32Exception e) {
            Console.WriteLine(Json.Serialize(new {ok=false,error=e.NativeErrorCode==1223 ? "Windows 授权已取消；需要授权后才能使用内置网络组件" : "无法启动 Windows 授权，请重新运行完整安装包"})); return 1;
        } catch(WebException e) {
            var response=e.Response as HttpWebResponse;
            string error=response!=null && response.StatusCode==HttpStatusCode.Unauthorized ? "网络组件授权已失效，请重新执行 Windows 授权" : "网络组件没有响应，请检查 ZeroTierOneService 服务是否运行或修复安装";
            Console.WriteLine(Json.Serialize(new {ok=false,error=error})); return 1;
        } catch(Exception e) {
            // Do not include HTTP bodies, keys, command arguments or full filesystem paths.
            string error=e is FileNotFoundException || e is DirectoryNotFoundException ? "未找到网络组件或本机授权，请运行完整安装包并完成首次 Windows 授权" : e is CryptographicException ? "此凭证不属于当前 Windows 用户，请重新执行 Windows 授权" : "本机网络授权失败，请重试或修复安装";
            Console.WriteLine(Json.Serialize(new {ok=false,error=error})); return 1;
        }
    }
}
